<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Item; use App\Models\StockTransaction; use App\Services\InventoryService; use Illuminate\Http\Request;
class InventoryController extends Controller { public function __construct(private readonly InventoryService $inventoryService) {} public function index(){ $items=Item::query()->get(); $ledger=StockTransaction::query()->latest('txn_at')->limit(100)->get(); $balances=$this->inventoryService->stockBalances(); return view('admin.inventory.index',compact('items','ledger','balances')); } public function storeItem(Request $r){ $d=$r->validate(['name'=>'required','sku'=>'required|unique:items,sku','uom'=>'required']); Item::query()->create($d+['reorder_level'=>$r->input('reorder_level',0)]); return back()->with('success','Item created'); } public function storeTxn(Request $r){ $d=$r->validate(['item_id'=>'required|exists:items,id','txn_type'=>'required|in:OPENING,IN,OUT,ADJUSTMENT','quantity'=>'required|numeric|min:0.001','txn_at'=>'required|date']); StockTransaction::query()->create($d+['unit_cost'=>$r->input('unit_cost',0),'remarks'=>$r->input('remarks')]); return back()->with('success','Stock txn posted'); }}
